--[=[
    @class Observer

    * 观察者模式, 用于监听容器中的数据流和行动.
]=]
local Observer = {}

Observer.__index = Observer

function Observer.new()
	local self = {}

	return setmetatable(self, Observer)
end

--[=[
	销毁观察者
]=]
function Observer:Dispose() end

export type Type = typeof(Observer.new())

return Observer
